import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const INTEGER_PATTERN = /^\d+$/;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}/;

function text(value: unknown): string {
  if (value === undefined || value === null) {
    return '';
  }
  return String(value).trim();
}

@Controller('api/v1')
export class FnSfr03104Controller {
  @Get('/change-histories')
  async listChangeHistories(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '시스템 관리자');
    const query = checks.queryOf(req.query);

    const targetType = text(query['targetType']);
    if (targetType === '' || targetType.length > 100) {
      throw new ApiError(400, 'VALIDATION_FAILED', '대상 유형을 100자 이내로 입력해 주세요.');
    }

    const targetIdText = text(query['targetId']);
    if (!INTEGER_PATTERN.test(targetIdText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '대상 식별자는 숫자로 입력해 주세요.');
    }

    const changedFrom = text(query['changedFrom']);
    if (changedFrom !== '' && !DATE_PATTERN.test(changedFrom)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '수정 일시 조회 시작 형식이 올바르지 않습니다.');
    }
    const changedTo = text(query['changedTo']);
    if (changedTo !== '' && !DATE_PATTERN.test(changedTo)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '수정 일시 조회 종료 형식이 올바르지 않습니다.');
    }

    const pageText = text(query['page']);
    if (pageText !== '' && !INTEGER_PATTERN.test(pageText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '페이지 번호가 올바르지 않습니다.');
    }
    const sizeText = text(query['size']);
    if (sizeText !== '' && !INTEGER_PATTERN.test(sizeText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '페이지 크기가 올바르지 않습니다.');
    }
    const page = pageText === '' ? 0 : Number(pageText);
    let size = sizeText === '' ? DEFAULT_SIZE : Number(sizeText);
    if (size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '페이지 크기가 올바르지 않습니다.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }

    return transaction(async (db) => {
      const params = {
        targetType,
        targetId: targetIdText,
        changedFrom: changedFrom === '' ? null : changedFrom,
        changedTo: changedTo === '' ? null : changedTo,
        size,
        offset: page * size,
      };
      const where = `target_type = :targetType
        AND target_id = CAST(:targetId AS bigint)
        AND (CAST(:changedFrom AS timestamptz) IS NULL OR changed_at >= CAST(:changedFrom AS timestamptz))
        AND (CAST(:changedTo AS timestamptz) IS NULL OR changed_at <= CAST(:changedTo AS timestamptz))`;

      const countRows = await db.query(
        `SELECT COUNT(*) AS "total" FROM change_history WHERE ${where}`,
        params,
      );
      const total = Number(countRows[0]['total']);

      const items = await db.query(
        `SELECT changed_at AS "changedAt",
          changer_id AS "changerId",
          before_content AS "beforeContent",
          after_content AS "afterContent"
        FROM change_history
        WHERE ${where}
        ORDER BY changed_at DESC, change_history_id DESC
        LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        params,
      );

      return { items, page, size, total };
    });
  }
}

