import { useState } from 'react';
import {
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  ErrorText,
  Field,
  Filters,
  NumberInput,
  Pager,
  Pairs,
  RefName,
  Tiles,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Column, Page, PageProps, Row } from '../kit';

const PAGE_SIZE = 20;

interface Condition {
  targetType: string;
  targetId: number | string;
  changedFrom: string;
  changedTo: string;
}

const EMPTY: Condition = { targetType: '', targetId: '', changedFrom: '', changedTo: '' };

export default function FnSfr03104Page({ role, notify }: PageProps) {
  const [draft, setDraft] = useState<Condition>(EMPTY);
  const [applied, setApplied] = useState<Condition | null>(null);
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [formError, setFormError] = useState('');

  const { data, error, loading } = useData<Page>(async () => {
    if (applied === null) {
      return { items: [], page: 0, size: PAGE_SIZE, total: 0 };
    }
    return call<Page>('GET', '/change-histories', role, undefined, {
      targetType: applied.targetType,
      targetId: applied.targetId,
      changedFrom: applied.changedFrom,
      changedTo: applied.changedTo,
      page,
      size: PAGE_SIZE,
    });
  }, [applied, page, role]);

  function search() {
    if (draft.targetType.trim() === '' || draft.targetId === '') {
      setFormError('대상 유형과 대상 식별자를 입력해 주세요.');
      return;
    }
    setFormError('');
    setPage(0);
    setApplied({ ...draft });
    notify('수정이력을 조회했습니다.');
  }

  function reset() {
    setDraft(EMPTY);
    setApplied(null);
    setFormError('');
    setPage(0);
  }

  const columns: Column[] = [
    { key: 'changedAt', label: '변경 일시', render: (row) => <DateText value={row.changedAt} time /> },
    { key: 'changerId', label: '변경자', render: (row) => <RefName table="employee" role={role} value={row.changerId} /> },
    { key: 'beforeContent', label: '변경 전 내용' },
    { key: 'afterContent', label: '변경 후 내용' },
  ];

  const total = data ? data.total : 0;
  const emptyText = applied === null ? '대상 유형과 대상 식별자를 입력하고 조회해 주세요.' : '수정이력이 없습니다.';

  return (
    <div className="bento">
      <section className="box span-8">
        <h2>수정이력</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="대상 유형" required>
            <TextInput value={draft.targetType} onChange={(v) => setDraft({ ...draft, targetType: v })} />
          </Field>
          <Field label="대상 식별자" required>
            <NumberInput value={draft.targetId} onChange={(v) => setDraft({ ...draft, targetId: v })} />
          </Field>
          <Field label="수정 일시 조회 시작">
            <DateInput value={draft.changedFrom} onChange={(v) => setDraft({ ...draft, changedFrom: v })} />
          </Field>
          <Field label="수정 일시 조회 종료">
            <DateInput value={draft.changedTo} onChange={(v) => setDraft({ ...draft, changedTo: v })} />
          </Field>
        </Filters>
        {formError !== '' && <ErrorText text={formError} />}
        {error !== '' && <ErrorText text={error} />}
        <Band total={total} />
        <DataTable
          columns={columns}
          rows={data ? data.items : []}
          onRowClick={(row) => setSelected(row)}
          empty={loading ? '불러오는 중입니다.' : emptyText}
        />
        <Pager page={page} size={PAGE_SIZE} total={total} onPage={setPage} />
      </section>
      <section className="box span-4">
        <h2>조회 건수</h2>
        <Tiles items={[['수정이력', <span>{total}건</span>]]} />
      </section>
      {selected !== null && (
        <Drawer title="수정이력 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['변경 일시', <DateText value={selected.changedAt} time />],
              ['변경자', <RefName table="employee" role={role} value={selected.changerId} />],
              ['변경 전 내용', <span>{String(selected.beforeContent ?? '')}</span>],
              ['변경 후 내용', <span>{String(selected.afterContent ?? '')}</span>],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
